import { useEffect, useRef } from 'react';

// Mantém a tela ativa (sem suspender nem escurecer) enquanto `active` for true.
// Usado durante a avaliação, que pode levar dezenas de segundos sem nenhuma
// interação do usuário — sem isso o celular/PC apagaria a tela no meio.
//
// Estratégia:
//  1. Screen Wake Lock API (Chrome/Edge, Android, iOS 16.4+, Safari/macOS 16.4+).
//     O lock cai sozinho quando a aba fica oculta, então re-adquirimos quando ela
//     volta a ficar visível.
//  2. Fallback (iOS < 16.4): reproduzir um vídeo mudo, minúsculo e invisível em
//     loop — o truque do NoSleep.js. O sistema não escurece a tela enquanto há
//     mídia tocando. Como a avaliação começa logo após um toque do usuário, o
//     autoplay do vídeo mudo inline é permitido.

// MP4 de ~5KB (1px, mudo) extraído do NoSleep.js — único formato necessário,
// já que o fallback só importa pro iOS antigo (Android/desktop têm Wake Lock).
const TINY_MP4 = 'data:video/mp4;base64,';

export function useWakeLock(active) {
  const sentinelRef = useRef(null);
  const videoRef = useRef(null);

  useEffect(() => {
    if (!active) return undefined;
    let cancelled = false;

    function startVideoFallback() {
      if (videoRef.current) return;
      const video = document.createElement('video');
      video.muted = true;
      video.defaultMuted = true;
      video.loop = true;
      video.setAttribute('muted', '');
      video.setAttribute('playsinline', '');
      video.setAttribute('title', 'Avaliação em andamento');
      video.src = TINY_MP4;
      video.style.cssText =
        'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;pointer-events:none;';
      document.body.appendChild(video);
      videoRef.current = video;
      video.play().catch(() => {});
    }

    async function acquire() {
      if ('wakeLock' in navigator) {
        try {
          const sentinel = await navigator.wakeLock.request('screen');
          if (cancelled) {
            sentinel.release().catch(() => {});
            return;
          }
          sentinelRef.current = sentinel;
          sentinel.addEventListener('release', () => {
            if (sentinelRef.current === sentinel) sentinelRef.current = null;
          });
          return;
        } catch {
          // negado ou não suportado de fato → fallback de vídeo
        }
      }
      if (!cancelled) startVideoFallback();
    }

    // O Wake Lock cai quando a aba fica oculta; re-adquire ao voltar a ficar visível.
    function onVisibility() {
      if (document.visibilityState === 'visible' && !cancelled && !sentinelRef.current) {
        acquire();
      }
    }

    acquire();
    document.addEventListener('visibilitychange', onVisibility);

    return () => {
      cancelled = true;
      document.removeEventListener('visibilitychange', onVisibility);
      if (sentinelRef.current) {
        sentinelRef.current.release().catch(() => {});
        sentinelRef.current = null;
      }
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.removeAttribute('src');
        try { videoRef.current.load(); } catch { /* noop */ }
        videoRef.current.remove();
        videoRef.current = null;
      }
    };
  }, [active]);
}
